452 | // NewIssue creates new issue with labels for repository.
453 | // The title will be cut off at 255 characters if it's longer than 255 characters.
454 | func NewIssue(ctx context.Context, repo *repo_model.Repository, issue *Issue, labelIDs []int64, uuids []string) (err error) {
